Hi Boris,

You ran into a bug in the Spec# verifier. The variation of your code below illustrates the bug. I am working on the fix and will commit it soon (I believe I have fixed it, but I am having trouble accessing the sources on CodePlex). 

  Peter


using System;
using Microsoft.Contracts;

public class B {
  [Pure] public int g()
  {
    return 0;
  }
}

public class C {
  [Rep] public B b = new B();  
}

public class D {
  [Rep] public C c = new C();

  public void f() {
    int m;
    m = c.b.g();
    assert false;  // verifies
  }
}
